const FULL_PRICE_CATEGORY_ORDER=["ТО - Техническое обслуживание","Двигатель и навесное оборудование","Трансмиссия","Ходовая часть и подвеска","Тормозная система","Рулевые рейки","Турбины","Шиномонтаж","Автоэлектрика","Чип-тюнинг","Автомойка","Система охлаждения","Кондиционер и климат-контроль","Топливная система","Выхлопная система","Сварочные работы"];
(function(){
  const fmt=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' ₽';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  const examples=document.getElementById('randomPriceExamples');
  if(examples){
    const pool=[...FULL_PRICE_DATA];
    for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
    const chosen=[];const cats=new Set();
    for(const item of pool){if(!cats.has(item.category)){chosen.push(item);cats.add(item.category);}if(chosen.length===7)break;}
    examples.innerHTML=chosen.map(x=>`<div class="price-row" role="button" tabindex="0" data-example-service="${encodeURIComponent(x.name)}" title="Записаться на услугу: ${esc(x.name)}"><span>${esc(x.name)}</span><b>от ${fmt(x.price)}</b></div>`).join('');examples.querySelectorAll('[data-example-service]').forEach(row=>{const go=()=>openBooking(decodeURIComponent(row.dataset.exampleService||''));row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}});});
  }
  const modal=document.getElementById('priceModal');
  const openBtn=document.getElementById('openPrice');
  const catsEl=document.getElementById('priceCatalogCategories');
  const content=document.getElementById('priceCatalogContent');
  const search=document.getElementById('priceCatalogSearch');
  const count=document.getElementById('priceCatalogCount');
  const book=document.getElementById('priceCatalogBook');
  const hint=document.getElementById('priceCatalogHint');
  let activeBookService='';
  if(!modal||!catsEl||!content)return;
  const groups=new Map();
  FULL_PRICE_DATA.forEach(x=>{if(!groups.has(x.category))groups.set(x.category,[]);groups.get(x.category).push(x);});
  const ordered=[...FULL_PRICE_CATEGORY_ORDER.filter(c=>groups.has(c)),...([...groups.keys()].filter(c=>!FULL_PRICE_CATEGORY_ORDER.includes(c)).sort((a,b)=>a.localeCompare(b,'ru')))];
  let active='__all__';let query='';
  function renderCategories(){
    const all=`<button class="price-cat-btn ${active==='__all__'?'active':''}" data-cat="__all__"><span>Все категории</span><em>${FULL_PRICE_DATA.length}</em></button>`;
    catsEl.innerHTML=all+ordered.map(c=>`<button class="price-cat-btn ${active===c?'active':''}" data-cat="${esc(c)}"><span>${esc(c)}</span><em>${groups.get(c).length}</em></button>`).join('');
    catsEl.querySelectorAll('.price-cat-btn').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.cat;renderCategories();renderContent();}));
  }
  function matches(x){if(active!=='__all__'&&x.category!==active)return false;if(!query)return true;const q=query.toLocaleLowerCase('ru');return x.name.toLocaleLowerCase('ru').includes(q)||x.category.toLocaleLowerCase('ru').includes(q);}
  function setActiveBookService(service=''){
    activeBookService=service;
    content.querySelectorAll('.price-catalog-item.is-active').forEach(el=>el.classList.remove('is-active'));
    if(service){
      const target=[...content.querySelectorAll('.price-catalog-item')].find(el=>decodeURIComponent(el.dataset.service||'')===service);
      if(target)target.classList.add('is-active');
      if(hint)hint.innerHTML=`Выбрано: <strong>${esc(service)}</strong>`;
      if(book){book.dataset.service=service;book.title=`Записаться на услугу: ${service}`;}
    }else{
      if(hint)hint.textContent='Нажмите на нужную услугу — сразу откроется запись именно на неё.';
      if(book){book.dataset.service='';book.title='Сначала выберите услугу из списка';}
    }
  }
  function bookCatalogService(service){
    if(!service)return;
    setActiveBookService(service);
    closeModal(modal);
    openBooking(service);
  }
  function renderContent(){
    const filtered=FULL_PRICE_DATA.filter(matches);
    count.textContent=`Найдено: ${filtered.length}`;
    activeBookService='';
    if(!filtered.length){content.innerHTML='<div class="price-catalog-empty">Ничего не найдено. Попробуйте изменить запрос.</div>';setActiveBookService('');return;}
    const showCats=active==='__all__'?ordered:[active];
    content.innerHTML=showCats.map(cat=>{const items=filtered.filter(x=>x.category===cat);if(!items.length)return '';return `<section class="price-category-section"><div class="price-category-title"><span>${esc(cat)}</span><small>${items.length} услуг</small></div><div class="price-items-grid">${items.map(x=>`<button type="button" class="price-catalog-item" data-service="${encodeURIComponent(x.name)}" title="Записаться на услугу: ${esc(x.name)}"><span>${esc(x.name)}</span><b>от ${fmt(x.price)}</b></button>`).join('')}</div></section>`;}).join('');
    content.querySelectorAll('.price-catalog-item').forEach(item=>{
      const service=decodeURIComponent(item.dataset.service||'');
      item.addEventListener('pointerenter',()=>setActiveBookService(service));
      item.addEventListener('focus',()=>setActiveBookService(service));
      item.addEventListener('click',()=>bookCatalogService(service));
    });
    setActiveBookService('');
    content.scrollTop=0;
  }
  renderCategories();renderContent();
  search?.addEventListener('input',()=>{query=search.value.trim();renderContent();});
  if(openBtn)openBtn.onclick=()=>{search.value='';query='';active='__all__';activeBookService='';renderCategories();renderContent();openModal('#priceModal');setTimeout(()=>search.focus(),120);};
  book?.addEventListener('click',()=>{const service=book.dataset.service||activeBookService;if(service){bookCatalogService(service);return;}if(hint){hint.innerHTML='<strong>Выберите услугу из списка.</strong> После наведения на неё эта кнопка привяжется к выбранной работе.';}content.animate([{boxShadow:'inset 0 0 0 0 rgba(255,106,0,0)'},{boxShadow:'inset 0 0 0 2px rgba(255,106,0,.28)'},{boxShadow:'inset 0 0 0 0 rgba(255,106,0,0)'}],{duration:520});});
})();
